WITH events AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx/10000.0>t.ma60 AND LAG(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate)<=LAG(t.ma60) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS matched FROM `newzl`.`hsj_stock_hq_basic` b JOIN `newzl`.`hsj_stock_code_info` s ON s.mktcode=b.mktcode AND s.tgtcode=b.tgtcode LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate WHERE s.name='上海电力'), qualified AS (SELECT mktcode,tgtcode FROM events GROUP BY mktcode,tgtcode HAVING SUM(CASE WHEN matched THEN 1 ELSE 0 END)>1) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
